#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <unistd.h>

#define MAX_PENDING 64
#define DNS_PORT 53
#define PROXY_LISTEN_PORT 8053
#define UPSTREAM_DNS "8.8.8.8"

typedef struct {
    uint16_t txid;
    uint16_t flags;
    uint16_t qdcount;
    uint16_t ancount;
    uint16_t nscount;
    uint16_t arcount;
} dns_header_t;

typedef struct {
    uint16_t txid;
    struct sockaddr_in client_addr;
    socklen_t client_len;
    time_t timestamp;
    int active;
} pending_query_t;

static pending_query_t pending[MAX_PENDING];
static uint32_t prng_state;
static uint16_t session_key;

/* PRNG seeded once at startup for transaction ID generation */
static void prng_init(void) {
    prng_state = (uint32_t)time(NULL);
    /* Derive session key from initial state */
    session_key = (uint16_t)(prng_state ^ (prng_state >> 16));
}

/* Linear congruential generator for TXID */
static uint16_t prng_next_txid(void) {
    prng_state = prng_state * 1103515245 + 12345;
    /* XOR with session_key for "additional entropy" */
    return (uint16_t)((prng_state >> 16) ^ session_key);
}

static int find_free_slot(void) {
    for (int i = 0; i < MAX_PENDING; i++) {
        if (!pending[i].active) return i;
    }
    return -1;
}

static int find_by_txid(uint16_t txid) {
    for (int i = 0; i < MAX_PENDING; i++) {
        if (pending[i].active && pending[i].txid == txid) return i;
    }
    return -1;
}

/* Expire stale entries older than 5 seconds */
static void expire_pending(void) {
    time_t now = time(NULL);
    for (int i = 0; i < MAX_PENDING; i++) {
        if (pending[i].active && (now - pending[i].timestamp) > 5) {
            pending[i].active = 0;
        }
    }
}

static void handle_client_query(int listen_fd, int upstream_fd,
                                 struct sockaddr_in *upstream_addr) {
    uint8_t buf[512];
    struct sockaddr_in client_addr;
    socklen_t client_len = sizeof(client_addr);

    ssize_t n = recvfrom(listen_fd, buf, sizeof(buf), 0,
                         (struct sockaddr *)&client_addr, &client_len);
    if (n < (ssize_t)sizeof(dns_header_t)) return;

    expire_pending();
    int slot = find_free_slot();
    if (slot < 0) return;

    /* Generate new TXID for upstream query */
    uint16_t new_txid = prng_next_txid();

    /* Store mapping */
    pending[slot].txid = new_txid;
    pending[slot].client_addr = client_addr;
    pending[slot].client_len = client_len;
    pending[slot].timestamp = time(NULL);
    pending[slot].active = 1;

    /* Rewrite TXID in packet */
    dns_header_t *hdr = (dns_header_t *)buf;
    hdr->txid = htons(new_txid);

    sendto(upstream_fd, buf, n, 0,
           (struct sockaddr *)upstream_addr, sizeof(*upstream_addr));
}

static void handle_upstream_response(int upstream_fd, int listen_fd) {
    uint8_t buf[512];
    struct sockaddr_in from_addr;
    socklen_t from_len = sizeof(from_addr);

    ssize_t n = recvfrom(upstream_fd, buf, sizeof(buf), 0,
                         (struct sockaddr *)&from_addr, &from_len);
    if (n < (ssize_t)sizeof(dns_header_t)) return;

    dns_header_t *hdr = (dns_header_t *)buf;
    uint16_t txid = ntohs(hdr->txid);

    int slot = find_by_txid(txid);
    if (slot < 0) return;

    /* Forward response back to original client */
    sendto(listen_fd, buf, n, 0,
           (struct sockaddr *)&pending[slot].client_addr,
           pending[slot].client_len);

    pending[slot].active = 0;
}

int main(int argc, char *argv[]) {
    (void)argc; (void)argv;

    prng_init();

    int listen_fd = socket(AF_INET, SOCK_DGRAM, 0);
    int upstream_fd = socket(AF_INET, SOCK_DGRAM, 0);
    if (listen_fd < 0 || upstream_fd < 0) {
        perror("socket");
        return 1;
    }

    struct sockaddr_in listen_addr = {0};
    listen_addr.sin_family = AF_INET;
    listen_addr.sin_port = htons(PROXY_LISTEN_PORT);
    listen_addr.sin_addr.s_addr = htonl(INADDR_LOOPBACK);

    if (bind(listen_fd, (struct sockaddr *)&listen_addr, sizeof(listen_addr)) < 0) {
        perror("bind");
        return 1;
    }

    struct sockaddr_in upstream_addr = {0};
    upstream_addr.sin_family = AF_INET;
    upstream_addr.sin_port = htons(DNS_PORT);
    inet_pton(AF_INET, UPSTREAM_DNS, &upstream_addr.sin_addr);

    fd_set readfds;
    int maxfd = (listen_fd > upstream_fd) ? listen_fd : upstream_fd;

    printf("DNS proxy listening on 127.0.0.1:%d\n", PROXY_LISTEN_PORT);

    while (1) {
        FD_ZERO(&readfds);
        FD_SET(listen_fd, &readfds);
        FD_SET(upstream_fd, &readfds);

        struct timeval tv = {1, 0};
        int ret = select(maxfd + 1, &readfds, NULL, NULL, &tv);
        if (ret < 0) break;

        if (FD_ISSET(listen_fd, &readfds)) {
            handle_client_query(listen_fd, upstream_fd, &upstream_addr);
        }
        if (FD_ISSET(upstream_fd, &readfds)) {
            handle_upstream_response(upstream_fd, listen_fd);
        }
    }

    close(listen_fd);
    close(upstream_fd);
    return 0;
}
